parameters.jsCode:
// Build the image prompt from the editorial item + news type.
// Hard rules:
//   - Never copy unlicensed editorial photography.
//   - Never present AI imagery as documentary evidence of the actual match.
//   - For RESULT/TRANSFER/BREAKING, include team identity only through permitted treatment (e.g. color schemes, generic kit silhouettes, official wordmarks if licensed).
//   - The cover must communicate the news: include score / headline / key event as on-image elements.
const newsType = $json.news_type;
const template = {
  'RESULT': {
    label: 'FULL-TIME',
    mood: 'post-match atmosphere, decisive',
    layout: 'center score, two team names, short Thai headline beneath',
  },
  'PREVIEW': {
    label: 'MATCH PREVIEW',
    mood: 'anticipatory, neutral',
    layout: 'team A vs team B in central composition, competition badge area',
  },
  'ANALYSIS': {
    label: 'TACTICAL ANALYSIS',
    mood: 'analytical, considered',
    layout: 'pitch zones, tactical arrows, short headline',
  },
  'TRANSFER': {
    label: 'TRANSFER NEWS',
    mood: 'business-of-football',
    layout: 'player silhouette center, from->to visual language, deal status line',
  },
  'BREAKING': {
    label: 'BREAKING NEWS',
    mood: 'urgent, high-contrast',
    layout: 'short factual headline dominant, low-bleed background',
  },
}[newsType] || { label: 'NEWS', mood: 'neutral', layout: 'headline-first' };

const prompt = {
  news_type: newsType,
  headline_th: $json.headline_th || '',
  subheadline_th: $json.subheadline_th || '',
  label: template.label,
  teams: $json.teams || [],
  score: $json.score || null,
  competition: $json.competition || '',
  key_visual: $json.key_visual || '',
  tone: template.mood,
  layout: template.layout,
  visual_constraints: [
    'professional football editorial design',
    'strong visual hierarchy',
    'FF90 identity (logo in safe margin)',
    'high readability on mobile and social',
    'no watermarks',
    'no copied editorial photography',
    'no false documentary representation',
    'no unlicensed logos',
  ],
  aspect_ratio: '16:9',
  size: { w: 1600, h: 900 },
};
return [{ json: { ...$json, image_prompt: prompt } }];

// Provider adapter. Returns a structured result. NEVER fakes a
// generated image when no provider is configured.
const providerStatus = $env.IMAGE_PROVIDER_STATUS || 'NOT_CONFIGURED';
const providerName = $env.IMAGE_PROVIDER_NAME || 'none';
if (providerStatus !== 'CONFIGURED') {
  return [{
    json: {
      provider: providerName,
      provider_status: 'NOT_CONFIGURED',
      request_id: null,
      output_asset: null,
      status: 'held',
      error: 'image_provider_not_configured',
    },
  }];
}
// When configured, the provider-specific HTTP node downstream will
// populate output_asset + request_id.
return [{
  json: {
    provider: providerName,
    provider_status: 'CONFIGURED',
    request_id: null,
    output_asset: null,
    status: 'pending',
    error: null,
  },
}];

// Visual relevance gate. The image rights are NOT enough on their own —
// the cover must communicate the news.
const prompt = $json.image_prompt || {};
const newsType = prompt.news_type || '';
const hasVisualCues = !!(prompt.teams?.length || prompt.score || prompt.headline_th || prompt.key_visual);
const relevant = hasVisualCues && ['RESULT','PREVIEW','ANALYSIS','TRANSFER','BREAKING'].includes(newsType);
return [{
  json: {
    ...$json,
    visual_relevance: relevant ? 'PASS' : 'FAIL',
    relevance_basis: { hasVisualCues, newsType },
  },
}];

// Derivative sizes — same six we already ship via ffmpeg.
const sizes = [
  { id: 'hero_16x9',     w: 1600, h: 900,  mime: 'image/jpeg' },
  { id: 'thumbnail',     w:  800, h: 450,  mime: 'image/jpeg' },
  { id: 'social_1x1',    w: 1200, h: 1200, mime: 'image/jpeg' },
  { id: 'feed_4x5',      w: 1080, h: 1350, mime: 'image/jpeg' },
  { id: 'vertical_9x16', w: 1080, h: 1920, mime: 'image/jpeg' },
  { id: 'web_optimized', w: 1600, h:  900, mime: 'image/webp' },
];
return [{ json: { ...$json, derivatives: sizes } }];

